// viz-types: origin bars+dest pie, cumulative area, port bars, balance stacks, share-path multi-line, port??origin scatter | layout: default

type ViewId = "origins" | "ports" | "balance" | "path";

const CORN = "#ca8a04";
const SOY = "#15803d";
const NAVY = "#0f172a";
