  const herdLabel = series === "allCattle" ? "All cattle" : "Beef cows";
  const priceLabel =
    priceMode === "cutout" ? "Choice cutout ($/cwt)" : "All-fresh retail ($/lb)";
  const priceUnit = priceMode === "cutout" ? "$/cwt" : "$/lb";

  return (
    <div
