                      value: priceUnit,
                      angle: 90,
                      position: "insideRight",
                      fill: SLATE,
                      fontSize: 10,
                    }}
                  />
                  <Tooltip />
                  <Legend />
                  <Bar
                    yAxisId="herd"
                    dataKey="herd"
                    name={herdLabel}
                    fill={NAVY}
                    radius={[4, 4, 0, 0]}
                    maxBarSize={28}
                  />
                  <Line
                    yAxisId="price"
                    type="monotone"
                    dataKey="price"
                    name={priceLabel}
                    stroke={AMBER}
                    strokeWidth={2.5}
                    dot={{ r: 3, fill: AMBER }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Long herd path"
            subtitle="Jan-1 inventory back to the 1975 peak (NASS rounded)"
