                    type="number"
                    dataKey="retail"
                    name="Retail"
                    unit="$"
                    tick={{ fill: SLATE, fontSize: 11 }}
                    domain={[5, 10]}
                  />
                  <ZAxis type="number" dataKey="cutout" range={[40, 160]} />
                  <Tooltip cursor={{ strokeDasharray: "3 3" }} />
                  <Scatter name="Year" data={scatter} fill={TEAL} />
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="2026 class stack"
            subtitle="Million head ??? calf crop is 2025 crop; others are Jan 1, 2026"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={classes}
                  layout="vertical"
                  margin={{ top: 8, right: 12, left: 8, bottom: 0 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fill: SLATE, fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="name"
                    width={128}
                    tick={{ fill: SLATE, fontSize: 10 }}
                  />
                  <Tooltip />
                  <Bar dataKey="head" name="M head" fill={TEAL} radius={[0, 4, 4, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "drought" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Drought share of cattle inventory"
            subtitle="Estimated % of US cattle in drought-rated areas + beef-cow ?? (M head)"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={drought} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fill: SLATE, fontSize: 11 }} />
                  <YAxis
                    yAxisId="d"
                    tick={{ fill: SLATE, fontSize: 11 }}
                    domain={[0, 70]}
                    label={{
                      value: "% in drought",
                      angle: -90,
                      position: "insideLeft",
                      fill: SLATE,
                      fontSize: 10,
                    }}
                  />
                  <YAxis
                    yAxisId="c"
                    orientation="right"
                    tick={{ fill: SLATE, fontSize: 11 }}
                    domain={[-1.5, 1]}
                  />
                  <Tooltip />
                  <Legend />
                  <Area
                    yAxisId="d"
                    type="monotone"
                    dataKey="drought"
                    name="% cattle in drought"
                    fill="#fbbf24"
                    stroke={AMBER}
                    fillOpacity={0.35}
                  />
                  <Bar
                    yAxisId="c"
                    dataKey="cowDelta"
                    name="Beef cow ?? (M)"
                    fill={ROSE}
                    maxBarSize={22}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="State beef-cow share ?? pasture stress"
            subtitle="Bubble color = drought severity band (analytical)"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="share"
                    name="Beef-cow share"
                    unit="%"
                    tick={{ fill: SLATE, fontSize: 11 }}
                  />
                  <YAxis
                    type="number"
                    dataKey="stress"
                    name="Pasture stress"
                    tick={{ fill: SLATE, fontSize: 11 }}
                    domain={[30, 80]}
                  />
                  <ZAxis type="number" dataKey="share" range={[60, 280]} />
                  <Tooltip cursor={{ strokeDasharray: "3 3" }} />
                  <Scatter name="States" data={states}>
                    {states.map((s) => (
                      <Cell key={s.name} fill={SEVERITY[s.severity] ?? AMBER} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "rebuild" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Rebuild vs contraction signals"
            subtitle="Green = expansion cue ?? red = still contracting ?? amber = mixed"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
