                    dot={{ r: 3 }}
                  />
                  <Line
                    type="monotone"
                    dataKey="cutout"
                    name="Choice cutout ($/cwt)"
                    stroke={AMBER}
                    strokeWidth={2.5}
                    dot={{ r: 3 }}
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

