                <ComposedChart data={overlay} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fill: SLATE, fontSize: 11 }} />
                  <YAxis
                    yAxisId="herd"
                    tick={{ fill: SLATE, fontSize: 11 }}
                    domain={series === "allCattle" ? [84, 98] : [26, 34]}
                    label={{
                      value: "M head",
                      angle: -90,
                      position: "insideLeft",
                      fill: SLATE,
                      fontSize: 10,
                    }}
                  />
                  <YAxis
                    yAxisId="price"
                    orientation="right"
                    tick={{ fill: SLATE, fontSize: 11 }}
                    domain={priceMode === "cutout" ? [180, 380] : [5, 10]}
                    label={{
                      value: priceUnit,
                      angle: 90,
                      position: "insideRight",
                      fill: SLATE,
                      fontSize: 10,
                    }}
                  />
                  <Tooltip />
                  <Legend />
                  <Bar
                    yAxisId="herd"
                    dataKey="herd"
                    name={herdLabel}
                    fill={NAVY}
                    radius={[4, 4, 0, 0]}
                    maxBarSize={28}
                  />
                  <Line
                    yAxisId="price"
                    type="monotone"
                    dataKey="price"
                    name={priceLabel}
                    stroke={AMBER}
                    strokeWidth={2.5}
